import fs from 'node:fs/promises';
import path from 'node:path';

const output = '.vercel/output/static';
const index = await fs.readFile(path.join(output, 'index.html'), 'utf8');
if (!index.includes('SIMANTAB Online') || !index.includes('SUPABASE_URL')) {
  throw new Error('Cloudflare build aborted: SIMANTAB HTML/Supabase bootstrap missing.');
}
for (const file of ['manifest.json', 'sw.js', 'supabase-local.js', 'jabfung-jenjang-enhancement.js']) {
  await fs.access(path.join(output, file));
}
// Pages uses the same static build output generated by Vercel's legacy pipeline.
// Cloudflare Pages Functions are sourced from web/functions, not the .vercel/functions directory.
await fs.writeFile(path.join(output, '_headers'), [
  '/*',
  '  X-Content-Type-Options: nosniff',
  '  X-Frame-Options: DENY',
  '  Referrer-Policy: strict-origin-when-cross-origin',
  '  Permissions-Policy: camera=(), microphone=(), geolocation=()',
  '  X-Robots-Tag: noindex',
  '',
  '/index.html',
  '  Cache-Control: no-store',
  '',
  '/sw.js',
  '  Cache-Control: no-store',
  '',
  '/manifest.json',
  '  Cache-Control: no-cache',
  ''
].join('\n'));
await fs.writeFile(path.join(output, '_routes.json'), JSON.stringify({
  version: 1, include: ['/api/*'], exclude: []
}, null, 2));
console.log(JSON.stringify({
  cloudflarePagesReady: true,
  outputDirectory: output,
  pagesFunctionRoutes: ['/api/bcks-thinking','/api/diklat-ai-read','/api/jabfung-ai-read'],
  productionCutoverPerformed: false,
  note: 'Build still bootstraps from Vercel: capture and pin an approved current HTML baseline before decommissioning Vercel.'
}));
